/***************************************************************************************************** 
 *
 * Given a list of directory info including directory path, and all the files with contents in this 
 * directory, you need to find out all the groups of duplicate files in the file system in terms of 
 * their paths.
 * 
 * A group of duplicate files consists of at least two files that have exactly the same content.
 * 
 * A single directory info string in the input list has the following format:
 * 
 * "root/d1/d2/.../dm f1.txt(f1_content) f2.txt(f2_content) ... fn.txt(fn_content)"
 * 
 * It means there are n files (f1.txt, f2.txt ... fn.txt with content f1_content, f2_content ... 
 * fn_content, respectively) in directory root/d1/d2/.../dm. Note that n >= 1 and m >= 0. If m = 0, it 
 * means the directory is just the root directory.
 * 
 * The output is a list of group of duplicate file paths. For each group, it contains all the file 
 * paths of the files that have the same content. A file path is a string that has the following 
 * format:
 * 
 * "directory_path/file_name.txt"
 * 
 * Example 1:
 * 
 * Input:
 * ["root/a 1.txt(abcd) 2.txt(efgh)", "root/c 3.txt(abcd)", "root/c/d 4.txt(efgh)", "root 4.txt(efgh)"]
 * Output:  
 * [["root/a/2.txt","root/c/d/4.txt","root/4.txt"],["root/a/1.txt","root/c/3.txt"]]
 * 
 * Note:
 * 
 * 	No order is required for the final output.
 * 	You may assume the directory name, file name and file content only has letters and digits, 
 * and the length of file content is in the range of [1,50].
 * 	The number of files given is in the range of [1,20000].
 * 	You may assume no files or directories share the same name in the same directory.
 * 	You may assume each given directory info represents a unique directory. Directory path and 
 * file info are separated by a single blank space.
 * 
 * Follow-up beyond contest:
 * 
 * 	Imagine you are given a real file system, how will you search files? DFS or BFS?
 * 	If the file content is very large (GB level), how will you modify your solution?
 * 	If you can only read the file by 1kb each time, how will you modify your solution?
 * 	What is the time complexity of your modified solution? What is the most time-consuming part 
 * and memory consuming part of it? How to optimize?
 * 	How to make sure the duplicated files you find are not false positive?
 * 
 ******************************************************************************************************/

class Solution {
    public List<List<String>> findDuplicate(String[] paths) {
        var map = new HashMap<String, List<String>>();

        for (var path : paths) {
            var tmp = path.split(" ");
            for (var i = 1; i < tmp.length; i++) {
                var index = tmp[i].indexOf('(');
                var name = tmp[0] + "/" + tmp[i].substring(0, index);
                var content = tmp[i].substring(index, tmp[i].length());

                var list = map.getOrDefault(content, new ArrayList());
                list.add(name);
                map.put(content, list);
            }
        }

        return map.values().stream().filter(x -> x.size() > 1).collect(Collectors.toList());
    }
}

public class Solution {
    public List < List < String >> findDuplicate(String[] paths) {
        List < String[] > list = new ArrayList < > ();
        for (String path: paths) {
            String[] values = path.split(" ");
            for (int i = 1; i < values.length; i++) {
                String[] name_cont = values[i].split("\\(");
                name_cont[1] = name_cont[1].replace(")", "");
                list.add(new String[] {
                    values[0] + "/" + name_cont[0], name_cont[1]
                });
            }
        }
        boolean[] visited = new boolean[list.size()];
        List < List < String >> res = new ArrayList < > ();
        for (int i = 0; i < list.size() - 1; i++) {
            if (visited[i])
                continue;
            List < String > l = new ArrayList < > ();
            for (int j = i + 1; j < list.size(); j++) {
                if (list.get(i)[1].equals(list.get(j)[1])) {
                    l.add(list.get(j)[0]);
                    visited[j] = true;
                }
            }
            if (l.size() > 0) {
                l.add(list.get(i)[0]);
                res.add(l);
            }
        }
        return res;
    }
}

public class Solution {
    public List < List < String >> findDuplicate(String[] paths) {
        HashMap < String, List < String >> map = new HashMap < > ();
        for (String path: paths) {
            String[] values = path.split(" ");
            for (int i = 1; i < values.length; i++) {
                String[] name_cont = values[i].split("\\(");
                name_cont[1] = name_cont[1].replace(")", "");
                List < String > list = map.getOrDefault(name_cont[1], new ArrayList < String > ());
                list.add(values[0] + "/" + name_cont[0]);
                map.put(name_cont[1], list);
            }
        }
        List < List < String >> res = new ArrayList < > ();
        for (String key: map.keySet()) {
            if (map.get(key).size() > 1)
                res.add(map.get(key));
        }
        return res;
    }
}
